SHARP_CHROMATIC = ["C", "C#", "D", "D#", "E", "F", "F#", "G", "G#", "A", "A#", "B"]
FLAT_CHROMATIC = ["C", "Db", "D", "Eb", "E", "F", "Gb", "G", "Ab", "A", "Bb", "B"]
FLAT_TONICS = {"F", "Bb", "Eb", "Ab", "Db", "Gb"}


class Scale:
    def __init__(self, tonic):
        self.tonic = tonic[0].upper() + tonic[1:]

    def chromatic(self):
        base = FLAT_CHROMATIC if self.tonic in FLAT_TONICS else SHARP_CHROMATIC
        start = base.index(self.tonic)
        return base[start:] + base[:start]

    def interval(self, intervals):
        chromatic = self.chromatic()
        notes = [chromatic[0]]
        index = 0
        for interval in intervals:
            index += {"m": 1, "M": 2, "A": 3}[interval]
            notes.append(chromatic[index % 12])
        return notes
